"""
    Convert bytes to KB/MB/GB/TB/s
    """
def format_bytes(size: Any) -> object {
    power = 2 ** 10;
    n = 0;
    power_labels = {0: 'B/s', 1: 'KB/s', 2: 'MB/s', 3: 'GB/s', 4: 'TB/s'};
    while (size > power) {
        size /= power;
        n += 1;
    }
    return " ".join((str(round(size, 2)), power_labels[n]));
}

