"""fac: Returns an array of factors for the given number
    Args:
    	num (int): number to list factors for
    Returns:
    	array: factors of num
    """
def fac(num: Any) -> object {
    output = [];
    for x in range(1, (num + 1)) {
        if (((num % x) == 0) and not ((num % x) in output)) {
            output.append(x);
        }
    }
    return output;
}
